                        if m_axis_tready_i = '1' then
                            m_axis_tvalid_o <= '0';
                            if s_axis_tlast_i = '1' then
                                state <= IDLE;
                            else
                                state <= IDLE; -- Assuming no pipelining for simplicity
                            end if;
                        end if;

                    when others =>
                        state <= IDLE;
                end case;
            end if;
        end if;
    end process;

end architecture rtl;

